import{_ as a,I as o,g as t,j as r}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Workspaces Overview","description":"Workspace templates in OmniCraft ERP, their key features, active modules, and upcoming plans.","frontmatter":{"title":"Workspaces Overview","description":"Workspace templates in OmniCraft ERP, their key features, active modules, and upcoming plans.","order":5},"headers":[],"relativePath":"docs/spaces/general.md","filePath":"docs/spaces/general.md"}'),i={name:"docs/spaces/general.md"};function s(n,e,l,c,d,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="🗂️-workspaces-overview" tabindex="-1">🗂️ Workspaces Overview <a class="header-anchor" href="#🗂️-workspaces-overview" aria-label="Permalink to &quot;🗂️ Workspaces Overview&quot;">​</a></h1><p>The architecture of <strong>OmniCraft ERP</strong> is built entirely on the concept of isolated workspaces. It is rare for an artisan, entrepreneur, or individual to limit themselves to a single focus. Trying to fit diverse activities into a single ledger inevitably leads to accounting distortions, inventory chaos, and analytical confusion.</p><p>Mixing everything into one pile ruins the economics of each individual project. In OmniCraft ERP, you can create independent workspaces for every distinct task, switching between them instantly via the sliding side drawer (Drawer).</p><hr><h2 id="🚀-first-run-profile-selection-onboarding" tabindex="-1">🚀 First Run &amp; Profile Selection Onboarding <a class="header-anchor" href="#🚀-first-run-profile-selection-onboarding" aria-label="Permalink to &quot;🚀 First Run &amp; Profile Selection Onboarding&quot;">​</a></h2><p>Upon launching a clean application for the first time, you are greeted by an onboarding screen to select the primary operational direction of your workshop:</p><ul><li><strong>Production &amp; Craft:</strong> raw materials tracking (MAC method), batch cost calculator, recipe specs, production workbench, and finished goods showroom.</li><li><strong>Services &amp; Repair Center:</strong> client book, work orders with stage tracking, standard labor hours price list, consumables deduction, and direct cash flow integration.</li></ul><h3 id="one-active-workspace-policy-free-standard-tiers" tabindex="-1">One Active Workspace Policy (Free &amp; Standard Tiers) <a class="header-anchor" href="#one-active-workspace-policy-free-standard-tiers" aria-label="Permalink to &quot;One Active Workspace Policy (Free &amp; Standard Tiers)&quot;">​</a></h3><ul><li><strong>1 Active Workspace:</strong> Free (up to 20 sales) and Standard licenses support strictly one simultaneously active workspace. You can operate either a production workshop or a service center.</li><li><strong>Flexible Direction Switch:</strong> if you wish to change your workshop profile, the current workspace can be sent to archive at any time via the side drawer or settings, freeing the slot to create a new space.</li><li><strong>15-Minute Grace Undo:</strong> protection against accidental archiving. Inside the side drawer, an instant undo action remains available for 15 minutes at no cost. After 15 minutes, unarchiving requires a PRO license to prevent serial multi-business abuse.</li><li><strong>Data Liberation Invariant:</strong> database backups (.db, .zip) and CSV exports are always freely accessible from archived spaces. OmniCraft ERP never holds your data hostage.</li><li><strong>PRO License:</strong> unlocks full multi-workspaces—simultaneous multi-workshop accounting, instant switching, and unlimited unarchiving.</li></ul><hr><h2 id="🏗️-workspace-templates-practical-examples" tabindex="-1">🏗️ Workspace Templates &amp; Practical Examples <a class="header-anchor" href="#🏗️-workspace-templates-practical-examples" aria-label="Permalink to &quot;🏗️ Workspace Templates &amp; Practical Examples&quot;">​</a></h2><p>You can select the template that best matches your specific activity:</p><h3 id="🔨-1-production-already-implemented" tabindex="-1">🔨 1. Production (Already Implemented) <a class="header-anchor" href="#🔨-1-production-already-implemented" aria-label="Permalink to &quot;🔨 1. Production (Already Implemented)&quot;">​</a></h3><p>This space is designed for classic artisanal or manufacturing cycles where physical raw materials undergo processing and assembly.</p><ul><li><strong>Example:</strong> A workshop making custom leather bags and lifestyle accessories.</li><li><strong>How it works:</strong> You purchase raw resources (materials warehouse), build spec sheets (recipe constructor), schedule jobs (workbench), transfer finished inventory to the showroom (showcase), and process retail or wholesale transactions.</li></ul><h3 id="💼-2-services-already-implemented" tabindex="-1">💼 2. Services (Already Implemented) <a class="header-anchor" href="#💼-2-services-already-implemented" aria-label="Permalink to &quot;💼 2. Services (Already Implemented)&quot;">​</a></h3><p>A template for business models centered around performing custom labor, repairs, bespoke craftsmanship, maintenance, or freelance work, where batch conveyor manufacturing is unnecessary.</p><ul><li><strong>Example:</strong> Product restoration, custom bespoke builds, tool tuning, sharpening, or workshop repair services.</li><li><strong>How it works:</strong> The Services workspace is unlocked when creating a new workspace in the side drawer. This profile includes dedicated service domain modules: <ul><li><strong>Services Catalog (&quot;Services&quot;):</strong> a flexible price list supporting both fixed-rate pricing and calculated models based on labor hours and overhead percentage.</li><li><strong>Service Orders (&quot;Orders&quot;):</strong> an operational order workspace with stage checklists, consumables logging, advance payment tracking, and balance due settlements. When completing an order, final payments are automatically recorded in cash flow (DDS).</li><li><strong>Client Directory (&quot;Clients&quot;):</strong> a contact book with past order history. Client tracking remains optional: walk-in orders can be processed instantly without mandatory client registration. The &quot;Workshop&quot; (tools, machines) and &quot;Warehouse&quot; (materials, components, spare parts) tabs are fully functional and connected to the unified master catalog shared with production.</li></ul></li></ul><h3 id="🛒-3-trade-retail-expected-soon" tabindex="-1">🛒 3. Trade &amp; Retail (Expected Soon) <a class="header-anchor" href="#🛒-3-trade-retail-expected-soon" aria-label="Permalink to &quot;🛒 3. Trade &amp; Retail (Expected Soon)&quot;">​</a></h3><p>Designed for commercial models that exclude a manufacturing phase.</p><ul><li><strong>Example:</strong> Reselling third-party supplies, such as specialty tools for crafters, finishes, or hardware.</li><li><strong>How it works:</strong> You purchase completed goods wholesale, log them directly into showroom stock, and sell them with a markup. The production queue is removed, streamlining the interface for pure retail operations.</li></ul><h3 id="🌐-4-education-digital-expected-soon" tabindex="-1">🌐 4. Education &amp; Digital (Expected Soon) <a class="header-anchor" href="#🌐-4-education-digital-expected-soon" aria-label="Permalink to &quot;🌐 4. Education &amp; Digital (Expected Soon)&quot;">​</a></h3><p>A workspace for distributing digital products where reproduction costs are effectively zero.</p><ul><li><strong>Example:</strong> Selling downloadable PDF patterns, templates, video tutorials, or hosting live masterclasses.</li><li><strong>How it works:</strong> Physical materials are not deducted upon sales. The tracking focus is oriented around digital content margins and analyzing the conversion efficiency of various marketing channels.</li></ul><h3 id="🌱-5-activities-hobbies-expected-soon" tabindex="-1">🌱 5. Activities &amp; Hobbies (Expected Soon) <a class="header-anchor" href="#🌱-5-activities-hobbies-expected-soon" aria-label="Permalink to &quot;🌱 5. Activities &amp; Hobbies (Expected Soon)&quot;">​</a></h3><p>A playground for non-commercial hobbies or projects in their earliest stages.</p><ul><li><strong>Example:</strong> Ceramic pottery hobbies, home brewing, or home gardening.</li><li><strong>How it works:</strong> You simply record purchases of materials and tools to see how much your passion project realistically costs.</li></ul><div class="tip custom-block"><p class="custom-block-title">Seamless Transition to Business</p><p>If your hobby begins generating revenue, the &quot;Activities &amp; Hobbies&quot; workspace can be converted into a commercial space (such as &quot;Production&quot; or &quot;Services&quot;) at any time, fully preserving your historical purchase ledger and recipe database.</p></div><h3 id="🏦-6-personal-expected-soon" tabindex="-1">🏦 6. Personal (Expected Soon) <a class="header-anchor" href="#🏦-6-personal-expected-soon" aria-label="Permalink to &quot;🏦 6. Personal (Expected Soon)&quot;">​</a></h3><p>A workspace for tracking personal assets, managing major life events, and goal setting.</p><ul><li><strong>Example:</strong> Home property, personal vehicle, high-end electronics, as well as significant life events (paying off a mortgage, major appliance purchases, receiving an inheritance, or tuition payments).</li><li><strong>How it works:</strong> In this space, you can organize your life: establish major activity directions based on your desires and goals. Goals can be financial (e.g., saving for renovations or paying down a loan) or personal (e.g., completing an educational course or mastering a new skill). You record your major personal property (non-financial assets) and log only significant, one-off inflow/outflow transactions.</li><li><strong>Core Advantage:</strong> You no longer need to log minor, everyday expenses (groceries, coffee, fuel)—that micromanagement becomes obsolete. In the global <strong>&quot;My Capital&quot;</strong> dashboard, the program automatically calculates your background spending based on bank balances. You simply update these balances periodically (e.g., once a month) to observe the dynamics of your net worth.</li></ul><hr><h2 id="💡-scaling-unlimited-workspaces" tabindex="-1">💡 Scaling: Unlimited Workspaces <a class="header-anchor" href="#💡-scaling-unlimited-workspaces" aria-label="Permalink to &quot;💡 Scaling: Unlimited Workspaces&quot;">​</a></h2><p>You are not restricted to a &quot;one business, one workspace&quot; model. The software allows you to create multiple workspaces of the same type if you run parallel projects.</p><p>For example, if you do both leatherworking and woodworking, you can set up two independent <strong>Production</strong> workspaces (e.g., &quot;Leathergoods&quot; and &quot;Wooden Furniture&quot;). If you also do restoration work and graphic design, you can create separate <strong>Services</strong> workspaces for them (e.g., &quot;Bespoke Restoration&quot; and &quot;Freelance Design&quot;). This completely separates their unique inventories, markups, and financials.</p><hr><h2 id="🏦-capital-consolidation-the-my-capital-module-already-implemented" tabindex="-1">🏦 Capital Consolidation: The &quot;My Capital&quot; Module (Already Implemented) <a class="header-anchor" href="#🏦-capital-consolidation-the-my-capital-module-already-implemented" aria-label="Permalink to &quot;🏦 Capital Consolidation: The &quot;My Capital&quot; Module (Already Implemented)&quot;">​</a></h2><p>Even though each project&#39;s financials are kept completely isolated, OmniCraft ERP features a global <strong>&quot;My Capital&quot;</strong> module in PRO mode (accessed via a dedicated button in the sidebar).</p><p>This module consolidates metrics from all your active workspaces and eliminates the need to track minor daily expenses (coffee, groceries, fuel, etc.).</p><h3 id="how-accounting-is-structured-in-the-my-capital-module" tabindex="-1">How accounting is structured in the &quot;My Capital&quot; module: <a class="header-anchor" href="#how-accounting-is-structured-in-the-my-capital-module" aria-label="Permalink to &quot;How accounting is structured in the &quot;My Capital&quot; module:&quot;">​</a></h3><ol><li><strong>My Accounts:</strong> In this tab, you register your actual bank cards, cash, deposits, or brokerage accounts. You <strong>do not</strong> need to log individual minor transactions. Instead, you simply visit periodically (e.g., once a week or month) and update the actual current balances.</li><li><strong>My Assets &amp; Major Transactions:</strong> Here, the program automatically pulls data from your <strong>&quot;Personal&quot;</strong> workspace (the value of your vehicle, home property, and major recorded one-off inflows/outflows).</li><li><strong>Automatic Consolidation:</strong> The program aggregates your account balances, raw material values on warehouses, showroom finished goods stock, and active equipment values across all your workspaces.</li><li><strong>Calculating Free Expenses (Delta):</strong> The program takes the cumulative net profit from your businesses, adds your major personal incomes, subtracts major expenses, and compares this to the actual net growth of your bank accounts. From this delta, the system automatically calculates your background, undocumented spending—grouping everyday micro-expenses and small miscellaneous receipts. This saves you from micromanagement and provides a clear graphical representation of your growing net worth.</li></ol><hr><h2 id="🧭-workspace-management-built-in-assistant" tabindex="-1">🧭 Workspace Management &amp; Built-in Assistant <a class="header-anchor" href="#🧭-workspace-management-built-in-assistant" aria-label="Permalink to &quot;🧭 Workspace Management &amp; Built-in Assistant&quot;">​</a></h2><p>In the application title bar, dedicated compact action buttons provide instant access to the entire ecosystem:</p><ul><li><strong>Workspaces Button (<code>⛯</code>):</strong> opens the sliding side drawer for rapid switching between production databases, personal finances, or specialized modules without cluttering the screen.</li><li><strong>Built-in AI Assistant (<code>✨</code>):</strong> toggled via the header button or the <code>Ctrl + J</code> shortcut. <ul><li>The assistant docks as a full-height sidebar that <strong>does not dim or block</strong> the underlying workspace, enabling real-time visibility into live inventory and financial updates.</li><li>The panel width is freely resizable by dragging its left border, and your preferred dimension is automatically remembered.</li><li><strong>Chat Drawer &amp; Projects (<code>≡</code>):</strong> the chat header features a slide-out drawer to manage multiple conversation threads. You can create separate chats for distinct goals, organize them into folders/projects (e.g., &quot;Fall 2026 Collection&quot; or &quot;Tax Audit&quot;), and pin crucial sessions to the top with a pushpin (📌).</li><li><strong>History &amp; Markdown Export:</strong> dialogue history is securely persisted per workspace in the database. Any conversation can be exported to Markdown with a single click.</li><li><strong>Lazy Message Loading:</strong> extended chats load in compact windows (25 messages per page) with a button to retrieve earlier turns, ensuring fast rendering and zero UI stutter.</li><li>The assistant seamlessly recognizes the active screen while maintaining full access to system-wide tools.</li><li>In the assistant settings (gear icon inside the chat header), the option <strong>&quot;Apply changes only on the active tab&quot;</strong> is enabled by default to safeguard against unintended mutations across other operational areas.</li></ul></li></ul>',45)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
